mkitem!{declare_lint ! { # [doc = " The `deref_into_dyn_supertrait` lint is emitted whenever there is a `Deref` implementation"] # [doc = " for `dyn SubTrait` with a `dyn SuperTrait` type as the `Output` type."] # [doc = ""] # [doc = " These implementations are \"shadowed\" by trait upcasting (stabilized since"] # [doc = " 1.86.0). The `deref` functions is no longer called implicitly, which might"] # [doc = " change behavior compared to previous rustc versions."] # [doc = ""] # [doc = " ### Example"] # [doc = ""] # [doc = " ```rust,compile_fail"] # [doc = " #![deny(deref_into_dyn_supertrait)]"] # [doc = " #![allow(dead_code)]"] # [doc = ""] # [doc = " use core::ops::Deref;"] # [doc = ""] # [doc = " trait A {}"] # [doc = " trait B: A {}"] # [doc = " impl<'a> Deref for dyn 'a + B {"] # [doc = "     type Target = dyn A;"] # [doc = "     fn deref(&self) -> &Self::Target {"] # [doc = "         todo!()"] # [doc = "     }"] # [doc = " }"] # [doc = ""] # [doc = " fn take_a(_: &dyn A) { }"] # [doc = ""] # [doc = " fn take_b(b: &dyn B) {"] # [doc = "     take_a(b);"] # [doc = " }"] # [doc = " ```"] # [doc = ""] # [doc = " {{produces}}"] # [doc = ""] # [doc = " ### Explanation"] # [doc = ""] # [doc = " The trait upcasting coercion added a new coercion rule, taking priority over certain other"] # [doc = " coercion rules, which causes some behavior change compared to older `rustc` versions."] # [doc = ""] # [doc = " `deref` can be still called explicitly, it just isn't called as part of a deref coercion"] # [doc = " (since trait upcasting coercion takes priority)."] pub DEREF_INTO_DYN_SUPERTRAIT , Allow , "`Deref` implementation with a supertrait trait object for output is shadowed by trait upcasting" , }}
